1: // Authentic Game Boy 3-Channel Chiptune Synthesizer & Sound Effects Engine
2: export class GameBoyAudio {
3:   constructor(musicTracks) {
4:     this.tracks = musicTracks || {};
5:     this.ctx = null;
6:     this.enabled = false;
7:     this.currentTrackName = null;
8:     this.timers = [];
9:     this.activeOscillators = new Set();
10:     this.masterGain = null;
11:   }
12: 
13:   init() {
14:     if (!this.ctx) {
15:       const AudioCtx = window.AudioContext || window.webkitAudioContext;
16:       if (!AudioCtx) return false;
17:       this.ctx = new AudioCtx();
18:       this.masterGain = this.ctx.createGain();
19:       this.masterGain.gain.value = 0.14;
20:       this.masterGain.connect(this.ctx.destination);
21:     }
22:     if (this.ctx.state === "suspended") {
23:       this.ctx.resume();
24:     }
25:     return true;
26:   }
27: 
28:   toggle() {
29:     this.enabled = !this.enabled;
30:     if (this.enabled) {
31:       this.init();
32:       if (this.currentTrackName) {
33:         this.playTrack(this.currentTrackName, true);
34:       }
35:     } else {
36:       this.stopMusic();
37:     }
38:     return this.enabled;
39:   }
40: 
41:   stopMusic() {
42:     for (const t of this.timers) clearTimeout(t);
43:     this.timers = [];
44:     for (const osc of this.activeOscillators) {
45:       try {
46:         osc.stop();
47:         osc.disconnect();
48:       } catch {}
49:     }
50:     this.activeOscillators.clear();
51:   }
52: 
53:   midiToFreq(midi) {
54:     return 440 * Math.pow(2, (midi - 69) / 12);
55:   }
56: 
57:   playTrack(trackName, forceRestart = false) {
58:     if (!forceRestart && this.currentTrackName === trackName && this.timers.length > 0) {
59:       return;
60:     }
61:     this.currentTrackName = trackName;
62:     if (!this.enabled) return;
63:     if (!this.init()) return;
64: 
65:     this.stopMusic();
66:     const track = this.tracks[trackName] || this.tracks.MUSIC_PALLET_TOWN;
67:     if (!track || !track.channels) return;
68: 
69:     const tickMs = Math.max(8, (track.tempo || 150) * 0.11);
70: 
71:     for (const ch of track.channels) {
72:       this.scheduleChannelLoop(ch, tickMs);
73:     }
74:   }
75: 
76:   scheduleChannelLoop(ch, tickMs) {
77:     if (!this.enabled || !this.ctx) return;
78:     let offsetMs = 0;
79:     const waveType = ch.ch === 3 ? "triangle" : "square";
80:     const chVol = ch.ch === 2 ? 0.35 : ch.ch === 1 ? 0.22 : 0.28;
81: 
82:     for (const [midi, ticks] of ch.notes) {
83:       const durMs = Math.max(20, ticks * tickMs);
84:       if (midi > 0) {
85:         const timer = setTimeout(() => {
86:           if (!this.enabled || !this.ctx) return;
87:           this.playNote(this.midiToFreq(midi), durMs * 0.9, waveType, chVol);
88:         }, offsetMs);
89:         this.timers.push(timer);
90:       }
91:       offsetMs += durMs;
92:     }
93: 
94:     if (offsetMs > 100) {
95:       const loopTimer = setTimeout(() => {
96:         if (this.enabled) this.scheduleChannelLoop(ch, tickMs);
97:       }, offsetMs);
98:       this.timers.push(loopTimer);
99:     }
100:   }
101: 
102:   playNote(freq, durMs, type = "square", volume = 0.25) {
103:     if (!this.ctx || !this.masterGain) return;
104:     const now = this.ctx.currentTime;
105:     const osc = this.ctx.createOscillator();
106:     const gain = this.ctx.createGain();
107:     osc.type = type;
108:     osc.frequency.setValueAtTime(freq, now);
109: 
110:     const durSec = durMs / 1000;
111:     gain.gain.setValueAtTime(volume, now);
112:     gain.gain.exponentialRampToValueAtTime(0.001, now + durSec);
113: 
114:     osc.connect(gain);
115:     gain.connect(this.masterGain);
116:     osc.start(now);
117:     osc.stop(now + durSec + 0.01);
118:     this.activeOscillators.add(osc);
119:     osc.onended = () => {
120:       this.activeOscillators.delete(osc);
121:       gain.disconnect();
122:     };
123:   }
124: 
125:   playSfx(kind) {
126:     if (!this.enabled) return;
127:     if (!this.init()) return;
128:     if (kind === "blip") {
129:       this.playNote(987.77, 45, "square", 0.35);
130:       setTimeout(() => this.playNote(1318.51, 55, "square", 0.35), 40);
131:     } else if (kind === "warp") {
132:       [523, 659, 784, 1046].forEach((f, i) => {
133:         setTimeout(() => this.playNote(f, 55, "square", 0.35), i * 45);
134:       });
135:     } else if (kind === "ledge") {
136:       [440, 587, 784].forEach((f, i) => {
137:         setTimeout(() => this.playNote(f, 50, "square", 0.3), i * 38);
138:       });
139:     } else if (kind === "bump") {
140:       this.playNote(130, 80, "square", 0.3);
141:     } else if (kind === "pika") {
142:       [1174, 1480, 1318, 1760].forEach((f, i) => {
143:         setTimeout(() => this.playNote(f, 65, "square", 0.4), i * 60);
144:       });
145:     } else if (kind === "thunder") {
146:       [1567, 1318, 1046, 880, 1760, 1396].forEach((f, i) => {
147:         setTimeout(() => this.playNote(f, 55, "sawtooth", 0.4), i * 45);
148:       });
149:     }
150:   }
151: }

