288:   // Get 8x8 tile ID at 8x8 tile coordinate (tx, ty) in zone
289:   getTileIdAt8x8(zone, tx, ty) {
290:     const bx = Math.floor(tx / 4);
291:     const by = Math.floor(ty / 4);
292:     const subX = ((tx % 4) + 4) % 4;
293:     const subY = ((ty % 4) + 4) % 4;
294:     const blockId = this.getBlockAt(zone, bx, by);
295:     const ts = this.tilesetsByConst[zone.tileset];
296:     const bst = this.bstData[ts.bstKey];
297:     const offset = blockId * 16 + subY * 4 + subX;
298:     return offset < bst.length ? bst[offset] : 0;
299:   }
300: 
301:   // In Pokémon Gen I (engine/overworld/player_state.asm _GetTileAndCoordsInFrontOfPlayer),
302:   // each 16x16 step cell (stepX, stepY) uses its lower-left 8x8 tile (stepX*2, stepY*2 + 1)
303:   // for passability, grass, warp tiles, ledges, and pair collisions!
304:   getCollisionTileAtStep(zone, stepX, stepY) {
305:     return this.getTileIdAt8x8(zone, stepX * 2, stepY * 2 + 1);
306:   }
307: 
308:   isStepPassable(zone, fromStepX, fromStepY, toStepX, toStepY) {
309:     const ts = this.tilesetsByConst[zone.tileset];
310:     const targetTile = this.getCollisionTileAtStep(zone, toStepX, toStepY);
311:     if (!ts.passableSet.has(targetTile)) {
312:       return false;
313:     }
314:     // Check elevation pair collisions (data/tilesets/pair_collision_tile_ids.asm)
315:     const fromTile = this.getCollisionTileAtStep(zone, fromStepX, fromStepY);
316:     for (const [tsName, t1, t2] of this.data.tilesets.pairCollisions) {
317:       if (tsName === zone.tileset) {
318:         if (
319:           (fromTile === t1 && targetTile === t2) ||
320:           (fromTile === t2 && targetTile === t1)
321:         ) {
322:           return false;
323:         }
324:       }
325:     }
326:     return true;
327:   }
