329:   // Check if moving in `dir` ("DOWN" | "LEFT" | "RIGHT") from (stepX, stepY) triggers a ledge hop
330:   canJumpLedge(zone, stepX, stepY, dir) {
331:     if (zone.tileset !== "OVERWORLD") return false;
332:     const standTile = this.getCollisionTileAtStep(zone, stepX, stepY);
333:     const dx = dir === "LEFT" ? -1 : dir === "RIGHT" ? 1 : 0;
334:     const dy = dir === "DOWN" ? 1 : 0;
335:     if (dx === 0 && dy === 0) return false;
336:     const frontTile = this.getCollisionTileAtStep(zone, stepX + dx, stepY + dy);
337:     for (const l of this.data.tilesets.ledges) {
338:       if (l.dir === dir && l.standTile === standTile && l.ledgeTile === frontTile) {
339:         return true;
340:       }
341:     }
342:     return false;
343:   }
