421:   // Draw a 16x16 OAM sprite into RGBA buffer with Game Boy OBP0 transparency
422:   drawSprite16x16(
423:     buf,
424:     bufW,
425:     bufH,
426:     destX,
427:     destY,
428:     spriteKey,
429:     dir = "DOWN",
430:     walking = false,
431:     flipWalk = false,
432:     pal,
433:     underGrass = false,
434:     zone = null,
435:     stepX = 0,
436:     stepY = 0
437:   ) {
438:     const sheet = this.spriteSheets[spriteKey] || this.spriteSheets.red;
439:     if (!sheet) return;
