557: export function loadZone(target, options = {}) {
558:   let zone = null;
559:   if (typeof target === "object" && target !== null) {
560:     zone = target;
561:   } else if (typeof target === "number") {
562:     zone = engine.zonesByNumber[target] || engine.zonesByRomId[target];
563:   } else if (typeof target === "string") {
564:     const clean = target.trim();
565:     if (clean.startsWith("0x") || clean.startsWith("0X")) {
566:       zone = engine.zonesByRomId[parseInt(clean, 16)];
567:     } else if (/^\d+$/.test(clean)) {
568:       zone = engine.zonesByNumber[parseInt(clean, 10)];
569:     } else {
570:       zone =
571:         engine.zonesByConst[clean.toUpperCase()] ||
572:         engine.allZones.find(
573:           (z) =>
574:             z.headerName.toLowerCase() === clean.toLowerCase() ||
575:             z.displayName.toLowerCase() === clean.toLowerCase()
576:         );
577:     }
578:   }
579:   if (!zone) return null;
580: 
581:   // Record outdoor map for LAST_MAP indoor exit warps
582:   if (state.currentZone && state.currentZone.romId < 0x25) {
583:     state.lastOutdoorMap = {
584:       mapConst: state.currentZone.constName,
585:       warpIndex: options.fromOutdoorWarpIndex ?? 0,
586:     };
587:   } else if (zone.romId >= 0x25 && zone.defaultParent) {
588:     if (!state.lastOutdoorMap || options.resetParent) {
589:       state.lastOutdoorMap = { ...zone.defaultParent };
590:     }
591:   }
592: 
593:   state.currentZone = zone;
594:   state.visitedZones.add(zone.constName);
595:   saveProgress();
596:   state.npcs = initZoneNpcs(zone);
597:   state.dialogue = null;
598: 
599:   const spawn =
600:     options.x !== undefined && options.y !== undefined
601:       ? { x: options.x, y: options.y, dir: options.dir || state.player.dir }
602:       : findDefaultSpawn(zone, options.warpIndex ?? null);
603: 
604:   state.player.x = spawn.x;
605:   state.player.y = spawn.y;
606:   state.player.renderX = spawn.x;
607:   state.player.renderY = spawn.y;
608:   state.player.dir = spawn.dir || "DOWN";
609:   state.player.walking = false;
610:   state.player.moveAnim = null;
611:   if (zone.romId >= 0x25 && state.player.mode === "bike") {
612:     state.player.mode = "walk";
613:   }
614:   const spawnTile = engine.getCollisionTileAtStep(zone, spawn.x, spawn.y);
615:   if (isWaterTile(zone, spawnTile)) {
616:     state.player.mode = "surf";
617:   } else if (state.player.mode === "surf") {
618:     state.player.mode = "walk";
619:   }
620: 
621:   // Place Pikachu 1 step behind Red (if tile is dry land)
622:   const behindOffsets = {
623:     DOWN: [0, -1],
624:     UP: [0, 1],
625:     LEFT: [1, 0],
626:     RIGHT: [-1, 0],
627:   };
628:   const [bx, by] = behindOffsets[state.player.dir] || [0, -1];
629:   const px = Math.max(0, Math.min(zone.width * 2 - 1, spawn.x + bx));
630:   const py = Math.max(0, Math.min(zone.height * 2 - 1, spawn.y + by));
631:   const pikaTile = engine.getCollisionTileAtStep(zone, px, py);
632:   const pikaOnWater = isWaterTile(zone, pikaTile);
633:   state.pikachu.x = pikaOnWater ? spawn.x : px;
634:   state.pikachu.y = pikaOnWater ? spawn.y : py;
635:   state.pikachu.renderX = state.pikachu.x;
636:   state.pikachu.renderY = state.pikachu.y;
637:   state.pikachu.dir = state.player.dir;
638:   state.pikachu.walking = false;
639:   state.pikachu.moveAnim = null;
640:   state.pikachu.spawnDelayed = false;
641:   syncPikachuOverworldState();
642: 
643:   audio.playTrack(zone.music);
644:   updateUIForCurrentZone();
645:   renderAllCanvases();
646:   return zone;
