657: function resolveWarpDestination(zone, warp) {
658:   let destConst = warp.destConst;
659:   let destWarpIdx = warp.destWarpIndex;
660:   if (destConst === "LAST_MAP") {
661:     if (
662:       state.lastOutdoorMap &&
663:       engine.zonesByConst[state.lastOutdoorMap.mapConst]
664:     ) {
665:       destConst = state.lastOutdoorMap.mapConst;
666:     } else if (zone.defaultParent) {
667:       destConst = zone.defaultParent.mapConst;
668:     } else {
669:       destConst = "PALLET_TOWN";
670:     }
671:   }
672:   // Check if we are exiting an elevator that had a floor chosen
673:   if (
674:     ELEVATOR_FLOORS[zone.constName] &&
675:     state.selectedElevatorDest[zone.constName]
676:   ) {
677:     const chosen = state.selectedElevatorDest[zone.constName];
678:     destConst = chosen.destConst;
679:     destWarpIdx = chosen.warpIndex;
680:   }
681:   return { destConst, destWarpIdx };
682: }
