1043: // Interact with what is in front of Red (A button / Space / Enter)
1044: export function interactInFront() {
1045:   if (state.battle) return;
1046:   if (state.dialogue) {
1047:     advanceDialogue();
1048:     return;
1049:   }
1050: 
1051:   const zone = state.currentZone;
1052:   const dx =
1053:     state.player.dir === "LEFT" ? -1 : state.player.dir === "RIGHT" ? 1 : 0;
1054:   const dy =
1055:     state.player.dir === "UP" ? -1 : state.player.dir === "DOWN" ? 1 : 0;
1056:   const fx = state.player.x + dx;
1057:   const fy = state.player.y + dy;
1058: 
1059:   // 1. Check if facing following Pikachu!
1060:   if (
1061:     state.pikachu.visible &&
1062:     state.pikachu.x === fx &&
1063:     state.pikachu.y === fy
1064:   ) {
1065:     openPikachuInteraction();
1066:     return;
1067:   }
1068: 
1069:   // 2. Check Elevator control panel
1070:   if (ELEVATOR_FLOORS[zone.constName]) {
1071:     for (const s of zone.signs) {
1072:       if (s.x === fx && s.y === fy) {
1073:         openElevatorMenu(zone.constName);
1074:         return;
1075:       }
1076:     }
1077:   }
1078: 
1079:   // 3. Check Signs (bg_events)
1080:   for (const s of zone.signs) {
1081:     if (s.x === fx && s.y === fy) {
1082:       audio.playSfx("blip");
1083:       openDialogue("SIGNPOST", s.text);
1084:       return;
1085:     }
1086:   }
1087: 
1088:   // 4. Check NPCs / Items (including 2 steps away across counter tiles in PokéCenters & Marts!)
1089:   const ts = engine.tilesetsByConst[zone.tileset];
1090:   const frontTile = engine.getCollisionTileAtStep(zone, fx, fy);
1091:   const acrossCounter = ts.counterSet.has(frontTile);
1092:   const checkCoords = [[fx, fy]];
1093:   if (acrossCounter) {
1094:     checkCoords.push([fx + dx, fy + dy]);
1095:   }
1096: 
1097:   for (const [cx, cy] of checkCoords) {
1098:     for (const npc of state.npcs) {
1099:       if (!npc.defaultVisible && !state.showHiddenObjects) continue;
1100:       if (npc.collected) continue;
1101:       if (npc.x === cx && npc.y === cy) {
1102:         triggerNpcDialogue(npc, zone);
1103:         return;
1104:       }
1105:     }
1106:   }
1107: }
