1712: function awardExpAndCheckLevelUp(mon, expGain, msgs) {
1713:   if (!mon || mon.level >= 100) return;
1714:   mon.exp = (mon.exp || 0) + expGain;
1715:   const needed = Math.max(20, mon.level * mon.level * 2);
1716:   if (mon.exp >= needed) {
1717:     mon.exp -= needed;
1718:     levelUpPokemon(mon, msgs, { interactive: true });
1719:   }
