1389: function calcGen1Damage(attacker, defender, move) {
1390:   if (!move || move.power === 0) {
1391:     return { damage: 0, effectiveness: 1.0, crit: false };
1392:   }
1393:   if (move.effect === "SPECIAL_DAMAGE_EFFECT") {
1394:     const fixed =
1395:       move.id === "SONICBOOM"
1396:         ? 20
1397:         : move.id === "DRAGON_RAGE"
1398:         ? 40
1399:         : attacker.level;
1400:     return { damage: fixed, effectiveness: 1.0, crit: false };
1401:   }
1402:   // Gen 1 critical hit rate based on base Speed
1403:   const critChance = Math.min(0.25, (attacker.spd || 50) / 512);
1404:   const crit = Math.random() < critChance;
1405:   const lv = crit ? attacker.level * 2 : attacker.level;
1406: 
1407:   const isSpecial = SPECIAL_TYPES.has(move.type);
1408:   const A = isSpecial ? attacker.spc : attacker.atk;
1409:   const D = Math.max(1, isSpecial ? defender.spc : defender.def);
1410: 
1411:   let baseDmg = Math.floor(
1412:     Math.floor((Math.floor((2 * lv) / 5 + 2) * move.power * A) / D) / 50
1413:   ) + 2;
1414: 
1415:   // STAB (Same-Type Attack Bonus)
1416:   if (attacker.types && attacker.types.includes(move.type)) {
1417:     baseDmg = Math.floor(baseDmg * 1.5);
1418:   }
1419: 
1420:   const effectiveness = getTypeEffectiveness(move.type, defender.types);
1421:   if (effectiveness === 0) {
1422:     return { damage: 0, effectiveness: 0, crit: false };
1423:   }
1424:   baseDmg = Math.floor(baseDmg * effectiveness);
1425: 
1426:   // Random variance (217..255)/255
1427:   const rand = 217 + Math.floor(Math.random() * 39);
1428:   const finalDmg = Math.max(1, Math.floor((baseDmg * rand) / 255));
1429:   return { damage: finalDmg, effectiveness, crit };
1430: }
