1636: function performMoveAttack(attacker, defender, move, isEnemyTurn = false) {
1637:   const msgs = [];
1638:   const prefix = isEnemyTurn ? `Enemy ${attacker.nickname}` : attacker.nickname;
1639: 
1640:   if (attacker.status === "SLP") {
1641:     if (Math.random() < 0.35) {
1642:       attacker.status = "OK";
1643:       msgs.push(`${prefix}\nwoke up!`);
1644:     } else {
1645:       msgs.push(`${prefix}\nis fast asleep!`);
1646:       return msgs;
1647:     }
1648:   }
1649:   if (attacker.status === "FRZ") {
1650:     msgs.push(`${prefix}\nis frozen solid!`);
1651:     return msgs;
1652:   }
1653:   if (attacker.status === "PAR" && Math.random() < 0.25) {
1654:     msgs.push(`${prefix}'s\nfully paralyzed!`);
1655:     return msgs;
1656:   }
1657: 
1658:   if (move.pp > 0) move.pp--;
1659:   msgs.push(`${prefix} used\n${move.name}!`);
1660: 
1661:   // Check accuracy
1662:   if (Math.random() * 100 > (move.accuracy || 100)) {
1663:     msgs.push(`${prefix}'s\nattack missed!`);
1664:     return msgs;
1665:   }
1666: 
1667:   // Status-only moves
1668:   if (move.power === 0) {
1669:     if (move.effect.includes("PARALYZE") || move.id === "THUNDER_WAVE" || move.id === "STUN_SPORE" || move.id === "GLARE") {
1670:       if (defender.status === "OK") {
1671:         defender.status = "PAR";
1672:         msgs.push(`${defender.nickname} was\nparalyzed! It may not attack!`);
1673:       } else {
1674:         msgs.push(`But it failed!`);
1675:       }
1676:     } else if (move.effect.includes("SLEEP") || move.id === "SLEEP_POWDER" || move.id === "SING" || move.id === "HYPNOSIS" || move.id === "SPORE") {
1677:       if (defender.status === "OK") {
1678:         defender.status = "SLP";
1679:         msgs.push(`${defender.nickname}\nfell asleep!`);
1680:       } else {
1681:         msgs.push(`But it failed!`);
1682:       }
1683:     } else if (move.effect.includes("POISON") || move.id === "POISONPOWDER" || move.id === "TOXIC") {
1684:       if (defender.status === "OK") {
1685:         defender.status = "PSN";
1686:         msgs.push(`${defender.nickname}\nwas poisoned!`);
1687:       } else {
1688:         msgs.push(`But it failed!`);
1689:       }
1690:     } else if (move.id === "RECOVER" || move.id === "SOFTBOILED" || move.id === "REST") {
1691:       attacker.hp = attacker.maxHp;
1692:       msgs.push(`${prefix}\nregained health!`);
1693:     } else if (move.effect.includes("DEFENSE_DOWN")) {
1694:       defender.def = Math.max(5, Math.floor(defender.def * 0.8));
1695:       msgs.push(`${defender.nickname}'s\nDEFENSE fell!`);
1696:     } else if (move.effect.includes("ATTACK_DOWN")) {
1697:       defender.atk = Math.max(5, Math.floor(defender.atk * 0.8));
1698:       msgs.push(`${defender.nickname}'s\nATTACK fell!`);
1699:     } else {
1700:       attacker.spd = Math.min(999, Math.floor(attacker.spd * 1.25));
1701:       msgs.push(`${prefix}'s\nstats rose!`);
1702:     }
1703:     return msgs;
1704:   }
1705: 
1706:   // Damaging move
1707:   const { damage, effectiveness, crit } = calcGen1Damage(attacker, defender, move);
1708:   if (effectiveness === 0) {
1709:     msgs.push(`It doesn't affect\n${defender.nickname}!`);
1710:     return msgs;
1711:   }
1712: 
1713:   defender.hp = Math.max(0, defender.hp - damage);
1714:   if (crit) {
1715:     msgs.push(`Critical hit!`);
1716:   }
1717:   if (effectiveness > 1) {
1718:     msgs.push(`It's super effective!`);
1719:   } else if (effectiveness < 1) {
1720:     msgs.push(`It's not very effective...`);
1721:   }
1722: 
1723:   // Secondary status effects
1724:   if (defender.hp > 0 && defender.status === "OK") {
1725:     if (move.effect.includes("PARALYZE_SIDE_EFFECT") && Math.random() < 0.2) {
1726:       defender.status = "PAR";
1727:       msgs.push(`${defender.nickname} was\nparalyzed!`);
1728:     } else if (move.effect.includes("BURN_SIDE_EFFECT") && Math.random() < 0.2) {
1729:       defender.status = "BRN";
1730:       msgs.push(`${defender.nickname} was\nburned!`);
1731:     } else if (move.effect.includes("POISON_SIDE_EFFECT") && Math.random() < 0.25) {
1732:       defender.status = "PSN";
1733:       msgs.push(`${defender.nickname} was\npoisoned!`);
1734:     } else if (move.effect.includes("FREEZE_SIDE_EFFECT") && Math.random() < 0.1) {
1735:       defender.status = "FRZ";
1736:       msgs.push(`${defender.nickname} was\nfrozen solid!`);
1737:     }
1738:   }
1739: 
1740:   // Drain moves
1741:   if (move.effect === "DRAIN_HP_EFFECT" && damage > 0) {
1742:     const healed = Math.max(1, Math.floor(damage / 2));
1743:     attacker.hp = Math.min(attacker.maxHp, attacker.hp + healed);
1744:     msgs.push(`Sucked health from\n${defender.nickname}!`);
1745:   }
1746: 
1747:   return msgs;
1748: }
