1750: export function evolvePokemon(mon, newSpeciesKey, msgs = [], options = {}) {
1751:   // Matches TryEvolvingMon & EvolveMon (engine/pokemon/evos_moves.asm:111-239)
1752:   const targetKey = String(newSpeciesKey || "").toUpperCase();
1753:   const newBase = POKEYELLOW_DATA.battle?.pokemonStats?.[targetKey];
1754:   if (!mon || !newBase) return false;
1755: 
1756:   const oldName = mon.nickname;
1757:   const newName = targetKey.replace(/_/g, " ");
1758:   if (!options.skipIntroText) {
1759:     msgs.push(`What? ${oldName}\nis evolving!`);
1760:   }
1761: 
1762:   const lv = mon.level;
1763:   const oldMaxHp = mon.maxHp;
1764:   const newMaxHp = Math.floor(((newBase.hp + 15) * 2 * lv) / 100) + lv + 10;
1765:   const hpDiff = Math.max(0, newMaxHp - oldMaxHp);
1766: 
1767:   mon.species = targetKey;
1768:   if (oldName === oldName.toUpperCase()) {
1769:     mon.nickname = newName; // RenameEvolvedMon (engine/pokemon/evos_moves.asm:159)
1770:   }
1771:   mon.maxHp = newMaxHp;
1772:   mon.hp = Math.min(newMaxHp, mon.hp + hpDiff); // engine/pokemon/evos_moves.asm:188-206
1773:   mon.atk = Math.floor(((newBase.atk + 15) * 2 * lv) / 100) + 5;
1774:   mon.def = Math.floor(((newBase.def + 15) * 2 * lv) / 100) + 5;
1775:   mon.spd = Math.floor(((newBase.spd + 15) * 2 * lv) / 100) + 5;
1776:   mon.spc = Math.floor(((newBase.spc + 15) * 2 * lv) / 100) + 5;
1777:   mon.types = newBase.types || ["NORMAL"];
1778:   mon.catchRate = newBase.catchRate ?? mon.catchRate;
1779:   mon.baseExp = newBase.baseExp ?? mon.baseExp;
1780: 
1781:   msgs.push(`${oldName} evolved\ninto ${newName}!`);
1782: 
1783:   // LearnMoveFromLevelUp on evolved species (engine/pokemon/evos_moves.asm:214)
1784:   for (const [learnLv, mId] of newBase.learnset || []) {
1785:     if (learnLv === lv && !mon.moves.some((mv) => mv.id === mId)) {
1786:       const newMove = getMoveObj(mId);
1787:       if (mon.moves.length < 4) {
1788:         mon.moves.push(newMove);
1789:       } else {
1790:         mon.moves[0] = newMove;
1791:       }
1792:       msgs.push(`${mon.nickname} learned\n${newMove.name}!`);
1793:     }
1794:   }
1795: 
1796:   state.caughtPokemon.add(targetKey);
1797:   saveProgress();
1798:   updateUIForCurrentZone();
1799:   return true;
1800: }
