1802: export function levelUpPokemon(mon, msgs = [], options = {}) {
1803:   if (!mon || mon.level >= 100) return false;
1804:   mon.level = Math.min(100, mon.level + 1);
1805:   if (mon.species === "PIKACHU") {
1806:     modifyPikachuHappiness("LEVELUP");
1807:   }
1808:   const base = POKEYELLOW_DATA.battle?.pokemonStats?.[mon.species];
1809:   if (base) {
1810:     const lv = mon.level;
1811:     const oldMaxHp = mon.maxHp;
1812:     mon.maxHp = Math.floor(((base.hp + 15) * 2 * lv) / 100) + lv + 10;
1813:     mon.hp = Math.min(mon.maxHp, mon.hp + Math.max(1, mon.maxHp - oldMaxHp));
1814:     mon.atk = Math.floor(((base.atk + 15) * 2 * lv) / 100) + 5;
1815:     mon.def = Math.floor(((base.def + 15) * 2 * lv) / 100) + 5;
1816:     mon.spd = Math.floor(((base.spd + 15) * 2 * lv) / 100) + 5;
1817:     mon.spc = Math.floor(((base.spc + 15) * 2 * lv) / 100) + 5;
1818:     msgs.push(`${mon.nickname} grew to\nlevel ${lv}!`);
1819: 
1820:     // Check data/pokemon/evos_moves.asm learnset for this level
1821:     for (const [learnLv, mId] of base.learnset || []) {
1822:       if (learnLv === lv && !mon.moves.some((mv) => mv.id === mId)) {
1823:         const newMove = getMoveObj(mId);
1824:         if (mon.moves.length < 4) {
1825:           mon.moves.push(newMove);
1826:         } else {
1827:           mon.moves[0] = newMove;
1828:         }
1829:         msgs.push(`${mon.nickname} learned\n${newMove.name}!`);
1830:       }
1831:     }
1832: 
1833:     // Check EVOLVE_LEVEL in data/pokemon/evos_moves.asm (EvolutionAfterBattle)
1834:     for (const evo of base.evolutions || []) {
1835:       if (evo.method === "LEVEL" && lv >= evo.level) {
1836:         if (options.interactive && state.battle) {
1837:           msgs.push({ type: "EVOLVE", mon, target: evo.target });
1838:         } else {
1839:           evolvePokemon(mon, evo.target, msgs);
1840:         }
1841:         break;
1842:       }
1843:     }
1844:   }
1845:   return true;
1846: }
