1931:     foe.moves[Math.floor(Math.random() * foe.moves.length)] || getMoveObj("TACKLE");
1932: 
1933:   const playerPriority = move.id === "QUICK_ATTACK" ? 1 : 0;
1934:   const enemyPriority = enemyMove.id === "QUICK_ATTACK" ? 1 : 0;
1935:   const playerFirst =
1936:     playerPriority > enemyPriority ||
1937:     (playerPriority === enemyPriority && pMon.spd >= foe.spd);
