export function toggleStartMenu() {
  if (state.battle || state.dialogue || isAtlasModalOpen()) return;
  heldDirs.clear();
  state.startMenu.open = !state.startMenu.open;
  state.startMenu.subView = null;
  state.startMenu.selectedDexSpecies = null;
  audio.playSfx("blip");
  renderStartMenu();
}

export function handleStartMenuInput(input) {
  const sm = state.startMenu;
  if (!sm.open) return;

  if (sm.subView) {
    if (input === "B" || input === "START") {
      audio.playSfx("blip");
      if (sm.selectedDexSpecies) {
        sm.selectedDexSpecies = null;
      } else {
        sm.subView = null;
      }
      renderStartMenu();
      return;
    }
    const subBody = document.getElementById("start-sub-body");
    const rows = subBody ? Array.from(subBody.querySelectorAll(".sub-list-row")) : [];
    if (rows.length > 0) {
      if (input === "UP") {
        sm.subCursor = (sm.subCursor - 1 + rows.length) % rows.length;
        audio.playSfx("blip");
        rows.forEach((r, i) => r.classList.toggle("selected", i === sm.subCursor));
        rows[sm.subCursor]?.scrollIntoView({ block: "nearest" });
      } else if (input === "DOWN") {
        sm.subCursor = (sm.subCursor + 1) % rows.length;
        audio.playSfx("blip");
        rows.forEach((r, i) => r.classList.toggle("selected", i === sm.subCursor));
        rows[sm.subCursor]?.scrollIntoView({ block: "nearest" });
      } else if (input === "A") {
        const targetRow = rows[sm.subCursor] || rows[0];
        if (targetRow) targetRow.click();
      }
    } else if (input === "A" && sm.selectedDexSpecies) {
      audio.playSfx("blip");
      sm.selectedDexSpecies = null;
      renderStartMenu();
    }
    return;
  }

  // Top-level DrawStartMenu (home/start_menu.asm:14-85)
  if (input === "UP") {
    // Wrap around from top (0) to bottom (6) (home/start_menu.asm:18-34)
    sm.cursor = (sm.cursor + 6) % 7;
    audio.playSfx("blip");
    renderStartMenu();
  } else if (input === "DOWN") {
    // Wrap around from bottom (6) to top (0) (home/start_menu.asm:35-51)
    sm.cursor = (sm.cursor + 1) % 7;
    audio.playSfx("blip");
    renderStartMenu();
  } else if (input === "B" || input === "START") {
    // CloseStartMenu (home/start_menu.asm:57-58)
    audio.playSfx("blip");
    sm.open = false;
    renderStartMenu();
  } else if (input === "A") {
    audio.playSfx("blip");
    const chosen = START_MENU_SECTIONS[sm.cursor];
    if (chosen === "EXIT") {
      sm.open = false;
      renderStartMenu();
    } else {
      sm.subView = chosen;
      sm.subCursor = 0;
      sm.selectedDexSpecies = null;
      renderStartMenu();
    }
  }
}

