3682: // Main 60fps loop
3683: let lastAnimTick = 0;
3684: let lastNpcTick = 0;
3685: const heldDirs = new Set();
3686: 
3687: function gameLoop(now) {
3688:   // 1. Update water & flower tile animation counter every 280ms (matching ~20 Game Boy frames)
3689:   if (now - lastAnimTick > 280) {
3690:     lastAnimTick = now;
3691:     engine.animCounter = (engine.animCounter + 1) & 7;
3692:     if (state.dialogue && state.dialogue.pikachuMood) {
3693:       renderDialogueModal();
3694:     }
3695:   }
3696: 
3697:   // 1b. Update active EvolveMon animation (engine/movie/evolution.asm:49-65)
3698:   if (state.battle && state.battle.menuState === "EVOLVING" && state.battle.evolution) {
3699:     const evo = state.battle.evolution;
3700:     if (now - evo.startTime >= evo.duration) {
3701:       completeEvolutionAnimation();
3702:     } else {
3703:       renderBattleModal();
3704:     }
3705:   }
3706: 
3707:   // 2. Update Player smooth step interpolation
3708:   if (state.player.moveAnim) {
3709:     const anim = state.player.moveAnim;
3710:     const t = Math.min(1, (now - anim.startTime) / anim.duration);
3711:     state.player.renderX = anim.fromX + (anim.toX - anim.fromX) * t;
3712:     let jumpArc = 0;
3713:     if (anim.isLedgeJump) {
3714:       jumpArc = -Math.sin(t * Math.PI) * 0.75;
3715:     }
3716:     state.player.renderY = anim.fromY + (anim.toY - anim.fromY) * t + jumpArc;
3717: 
3718:     if (state.pikachu.moveAnim) {
3719:       const pa = state.pikachu.moveAnim;
3720:       state.pikachu.renderX = pa.fromX + (pa.toX - pa.fromX) * t;
3721:       state.pikachu.renderY = pa.fromY + (pa.toY - pa.fromY) * t;
3722:     }
3723: 
3724:     if (t >= 1) {
3725:       state.player.x = anim.toX;
3726:       state.player.y = anim.toY;
3727:       state.player.renderX = anim.toX;
3728:       state.player.renderY = anim.toY;
3729:       state.player.walking = false;
3730:       state.player.moveAnim = null;
3731: 
3732:       if (state.pikachu.moveAnim) {
3733:         state.pikachu.x = state.pikachu.moveAnim.toX;
3734:         state.pikachu.y = state.pikachu.moveAnim.toY;
3735:         state.pikachu.renderX = state.pikachu.x;
3736:         state.pikachu.renderY = state.pikachu.y;
3737:         state.pikachu.walking = false;
3738:         state.pikachu.moveAnim = null;
3739:       }
3740: 
3741:       onPlayerStepCompleted();
3742:     }
3743:   } else if (heldDirs.size > 0 && !state.dialogue && !state.battle) {
3744:     const lastDir = Array.from(heldDirs).pop();
3745:     attemptStep(lastDir);
3746:   }
3747: 
3748:   // 3. Fluid 60fps NPC movement & idle turning (matches engine/overworld/movement.asm UpdateNPCSprite)
3749:   const zone = state.currentZone;
3750:   const ts = engine.tilesetsByConst[zone.tileset];
3751:   for (const npc of state.npcs) {
3752:     if (!npc.defaultVisible && !state.showHiddenObjects) continue;
3753:     if (npc.collected) continue;
3754: 
3755:     // 3a. Interpolate active 16-frame step animation (UpdateSpriteInWalkingAnimation)
3756:     if (npc.moveAnim) {
3757:       const na = npc.moveAnim;
3758:       const nt = Math.min(1, (now - na.startTime) / na.duration);
3759:       npc.renderX = na.fromX + (na.toX - na.fromX) * nt;
3760:       npc.renderY = na.fromY + (na.toY - na.fromY) * nt;
3761:       npc.isWalking = nt > 0.12 && nt < 0.88;
3762:       if (nt >= 1) {
3763:         npc.renderX = npc.x;
3764:         npc.renderY = npc.y;
3765:         npc.isWalking = false;
3766:         npc.moveAnim = null;
3767:       }
3768:       continue;
3769:     }
3770: 
3771:     // 3b. Per-NPC random movement delay timer (SPRITESTATEDATA2_MOVEMENTDELAY)
3772:     if (state.dialogue || state.battle) continue;
3773:     if (now < (npc.nextMoveTime || 0)) continue;
3774:     npc.nextMoveTime = now + 650 + Math.random() * 1450;
3775: 
3776:     if (npc.movement === "WALK") {
3777:       const dirs =
3778:         npc.dir === "UP_DOWN"
3779:           ? ["UP", "DOWN"]
3780:           : npc.dir === "LEFT_RIGHT"
3781:           ? ["LEFT", "RIGHT"]
3782:           : ["DOWN", "UP", "LEFT", "RIGHT"];
3783:       const d = dirs[Math.floor(Math.random() * dirs.length)];
3784:       npc.facing = d;
3785:       const dx = d === "LEFT" ? -1 : d === "RIGHT" ? 1 : 0;
3786:       const dy = d === "UP" ? -1 : d === "DOWN" ? 1 : 0;
3787:       const nx = npc.x + dx;
3788:       const ny = npc.y + dy;
3789: 
3790:       if (
3791:         Math.abs(nx - npc.originX) <= 2 &&
3792:         Math.abs(ny - npc.originY) <= 2 &&
3793:         nx >= 0 &&
3794:         nx < zone.width * 2 &&
3795:         ny >= 0 &&
3796:         ny < zone.height * 2 &&
3797:         !(nx === state.player.x && ny === state.player.y) &&
3798:         !(state.pikachu.visible && nx === state.pikachu.x && ny === state.pikachu.y) &&
3799:         !state.npcs.some(
3800:           (other) =>
3801:             other !== npc &&
3802:             !other.collected &&
3803:             (other.defaultVisible || state.showHiddenObjects) &&
3804:             other.x === nx &&
3805:             other.y === ny
3806:         ) &&
3807:         engine.isStepPassable(zone, npc.x, npc.y, nx, ny)
3808:       ) {
3809:         const destTile = engine.getCollisionTileAtStep(zone, nx, ny);
3810:         if (!ts.doorSet.has(destTile) && !ts.warpSet.has(destTile)) {
3811:           const fromX = npc.x;
3812:           const fromY = npc.y;
3813:           npc.x = nx;
3814:           npc.y = ny;
3815:           npc.stepParity = !npc.stepParity;
3816:           npc.isWalking = true;
3817:           npc.moveAnim = {
3818:             fromX,
3819:             fromY,
3820:             toX: nx,
3821:             toY: ny,
3822:             startTime: now,
3823:             duration: 265, // 16 Game Boy frames at 60fps
3824:           };
3825:         }
3826:       }
3827:     } else if (
3828:       npc.movement === "STAY" &&
3829:       (npc.dir === "ANY_DIR" || npc.dir === "UP_DOWN" || npc.dir === "LEFT_RIGHT")
3830:     ) {
3831:       // ChangeFacingDirection in engine/overworld/movement.asm:144, 245
3832:       const dirs =
3833:         npc.dir === "UP_DOWN"
3834:           ? ["UP", "DOWN"]
3835:           : npc.dir === "LEFT_RIGHT"
3836:           ? ["LEFT", "RIGHT"]
3837:           : ["DOWN", "UP", "LEFT", "RIGHT"];
3838:       npc.facing = dirs[Math.floor(Math.random() * dirs.length)];
3839:     }
3840:   }
3841: 
3842:   renderAllCanvases();
3843:   requestAnimationFrame(gameLoop);
3844: }
