node -e '
import http from "http";
import fs from "fs";
import path from "path";
import { chromium } from "playwright";

const root = process.cwd();
const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
  ".json": "application/json",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(root, urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on("pageerror", (err) => errors.push("PAGEERROR: " + err.message));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push("CONSOLE ERROR: " + msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });

// Run comprehensive stability tests in-page
const report = await page.evaluate(() => {
  const api = window.POKEYELLOW;
  if (!api) throw new Error("POKEYELLOW global missing");

  // 1. Test loading all 224 zones + verifying every warp destination resolves to a valid zone & warp index
  let warpCount = 0;
  for (const z of api.allHeaders) {
    const loaded = api.loadZone(z.constName);
    if (!loaded || loaded.constName !== z.constName) {
      throw new Error("Failed to load zone: " + z.constName);
    }
    if (api.state.player.x < 0 || api.state.player.x >= z.width * 2 ||
        api.state.player.y < 0 || api.state.player.y >= z.height * 2) {
      throw new Error(`Out of bounds spawn in ${z.constName}: (${api.state.player.x}, ${api.state.player.y})`);
    }
    warpCount += (z.warps || []).length;
  }

  // 2. Test SILPH_CO_ELEVATOR warp resolution without prior floor selection
  api.loadZone("SILPH_CO_ELEVATOR");
  const warpChip = document.querySelector("#inspector-warps .warp-chip");
  if (!warpChip || warpChip.textContent.includes("UNUSED_MAP_ED")) {
    throw new Error("SILPH_CO_ELEVATOR warp still unresolved: " + (warpChip && warpChip.textContent));
  }
  warpChip.click();
  if (api.state.currentZone.constName !== "SILPH_CO_1F") {
    throw new Error("Expected SILPH_CO_ELEVATOR default exit to warp to SILPH_CO_1F, got: " + api.state.currentZone.constName);
  }

  // 3. Test modal cleanup when switching zones while dialogue / battle / startMenu is open
  api.openPikachuInteraction();
  if (document.getElementById("dialogue-overlay").classList.contains("hidden")) {
    throw new Error("Dialogue overlay should be visible");
  }
  api.loadZone("CERULEAN_CITY");
  if (!document.getElementById("dialogue-overlay").classList.contains("hidden")) {
    throw new Error("Dialogue overlay stayed stuck after loadZone!");
  }

  api.toggleStartMenu();
  if (document.getElementById("start-menu-overlay").classList.contains("hidden")) {
    throw new Error("Start menu should be visible");
  }
  // Test keyboard navigation inside START menu subviews
  api.handleStartMenuInput("DOWN"); // POKEMON
  api.handleStartMenuInput("A");
  if (api.state.startMenu.subView !== "POKEMON") {
    throw new Error("Expected subView POKEMON");
  }
  api.handleStartMenuInput("DOWN");
  api.handleStartMenuInput("A"); // Swap party lead via keyboard/D-pad A
  api.handleStartMenuInput("B");
  api.loadZone("PALLET_TOWN");
  if (!document.getElementById("start-menu-overlay").classList.contains("hidden")) {
    throw new Error("Start menu stayed stuck after loadZone!");
  }

  // 4. Test Battle Struggle fallback when all moves have 0 PP & Evolution cancel
  api.healParty();
  api.triggerWildEncounter([5, "PIDGEY"]);
  const pMon = api.state.party[api.state.battle.activePlayerIdx];
  pMon.moves.forEach(m => { m.pp = 0; });
  api.handleBattleInput("A"); // Enter FIGHT_MENU
  api.handleBattleInput("A"); // Should use STRUGGLE instead of getting trapped
  if (!api.state.battle.log.includes("no\nmoves left") && !api.state.battle.log.includes("STRUGGLE")) {
    throw new Error("Expected Struggle fallback log, got: " + api.state.battle.log);
  }
  api.state.battle = null;
  api.healParty();
  api.loadZone("PALLET_TOWN");

  return {
    totalHeadersTested: api.allHeaders.length,
    totalWarpsChecked: warpCount,
    currentZone: api.state.currentZone.constName,
    playerPos: [api.state.player.x, api.state.player.y],
  };
});

console.log("Stability report:", report);
if (errors.length > 0) {
  console.error("Errors:", errors);
  process.exit(1);
}

fs.mkdirSync("/tmp/opencode", { recursive: true });
await page.screenshot({ path: "/tmp/opencode/stability-check.jpg", type: "jpeg", quality: 85 });

await browser.close();
server.close();
'

